"""Derive tables from existing JSON only; no project imports or timing operations."""
import hashlib,json
from collections import defaultdict
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
OUT=Path(__file__).resolve().parent
sources={}
def read(name):
 p=ROOT/name; sources[name]={'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size};return json.loads(p.read_text(encoding='utf-8'))
def means(rows,keys):return {k:sum(r[k] for r in rows)/len(rows)/1000 for k in keys}
def coarse(name,group=None):
 d=read(name); rows=d['attempts']; keys=[k for k in rows[0] if k.endswith('_ns')]
 result={'source':name,'json_pointer':'/attempts','attempts':len(rows),'mean_us':means(rows,keys),'note':d.get('timing_note'),'native_entries':sum(r.get('native_entries',0) for r in rows),'runner':d['runner']}
 if group:
  result['by_function']={fn:{'attempts':len(rs),'mean_us':means(rs,keys)} for fn in sorted({r['function'] for r in rows}) if (rs:=[r for r in rows if r['function']==fn])}
 if len(rows)>1:
  result['excluding_first_attempt']={'attempts':len(rows)-1,'mean_us':means(rows[1:],keys)}
 return result
s18=read('wave14-capture/capture/s18-other/summary.json'); report=read('wave14-capture/capture/s18-report/summary.json')
selected=[]
for i,r in enumerate(s18['rows']):
 if r['function'] in {'Chaosgame.create_image_chaos','Richards.run'}:continue
 raw='wave14-capture/capture/s18-other/'+r['program']+'/data.json'; d=read(raw)
 rr=next(x for x in d['rows'] if x['function']==r['function']);j=d['rows'].index(rr)
 assert r['valid'] and rr['valid']
 assert all(a['components_reconcile'] and a['attempt_ns']==sum(a['exclusive_ns'].values()) for a in rr['attempts'])
 keys=list(rr['attempts'][0]['exclusive_ns'])
 calc={k.removesuffix('_ns'):sum(a['exclusive_ns'][k] for a in rr['attempts'])/len(rr['attempts'])/1000 for k in keys}
 assert all(abs(calc[k]-r['mean_exclusive_us'][k+'_ns'])<1e-8 for k in calc)
 hist=next(x for x in report['historical_boundary']['rows'] if x['function']==r['function'])
 selected.append({'program':r['program'],'function':r['function'],'line':r['line'],'attempts':len(rr['attempts']),'mean_attempt_us':sum(a['attempt_ns'] for a in rr['attempts'])/len(rr['attempts'])/1000,'mean_exclusive_us':calc,'program_lookup_chronological_us':[a['exclusive_ns']['program_lookup_ns']/1000 for a in rr['attempts']],'raw_source':raw,'raw_json_pointer':f'/rows/{j}/attempts','summary_json_pointer':f'/rows/{i}','fresh_gate_python_us':r['fresh_gate_python_us'],'fresh_gate_complete_compiled_us':r['fresh_gate_complete_compiled_us'],'fresh_gate_note':r['context_note'],'count_context_separate_from_timing':hist['count_means'],'integrity':d['integrity'],'source_runtime':d['source'],'instrumentation':rr['instrumentation'],'limitations':d['limitations']})
barnes=coarse('wave15-depth2/depth2/barnes-native-phase.json')
fft=coarse('wave11-ledger/gap-ledger/work/scimark/phases.json',True)
ray=coarse('wave11-ledger/gap-ledger/work/raytrace/phases.json')
probe=read('wave13-depth/depth/boundary-phases.json');ticks=probe['native_exclusive_ticks'];freq=ticks[-2]; probe_n=len(probe['attempts'])
probe_out={'source':'wave13-depth/depth/boundary-phases.json','attempts':probe_n,'timer_switches':ticks[-1],'mean_us_per_attempt':dict(zip(probe['native_tick_labels'][:5],[v/freq*1e6/probe_n for v in ticks[:5]])),'warning':probe['warning']}
ladders={name:read('wave13-depth/depth/ladder-v3-'+name+'-summary.json') for name in ['scimark','raytrace']}
weighted=defaultdict(float);total=0;byregion={}
for r in selected:
 byregion[r['function']]=r['mean_attempt_us']*r['attempts'];total+=byregion[r['function']]
 for k,v in r['mean_exclusive_us'].items():weighted[k]+=v*r['attempts']
rank=lambda d:sorted(d.items(),key=lambda kv:kv[1],reverse=True)
largest=rank(byregion)[0][0];without=defaultdict(float)
for r in selected:
 if r['function']!=largest:
  for k,v in r['mean_exclusive_us'].items():without[k]+=v*r['attempts']
aggregation={'meaning':'Sum of these 36 instrumented attempts, with observed counts only; not a workload-population total, a gate estimate, or a speedup bound. No kernel context is pooled.','attempts':sum(r['attempts'] for r in selected),'total_us':total,'by_component_us':dict(rank(weighted)),'by_region_us':dict(rank(byregion)),'largest_region':largest,'without_largest_region_us':total-byregion[largest],'without_largest_by_component_us':dict(rank(without)),'top_individual_mean_component_us':sorted([{'function':r['function'],'component':k,'mean_us':v} for r in selected for k,v in r['mean_exclusive_us'].items()],key=lambda r:r['mean_us'],reverse=True)[:3]}
missing=['Barnes: named other subcomponents not separated in current wave15 phase record; first preparation is included in coarse residual.','FFT: result conversion/status is included in native; no separate result number. Shape preparation and binding are combined in other. No named-other partition.','Raytrace: only one cold attempt with seven native entries; warmed per-call load/guards/result/writeback and named-other partition are absent.','No current integrated wave16 context is measured here. Existing instruments classify costs with observer overhead; a causal direct-access saving is not obtained by summing their buckets.']
data={'derivation_only':True,'new_measurements':False,'runtime_sources_imported':False,'units':'microseconds per instrumented attempt unless labeled otherwise','heldout':selected,'kernels':{'barnes_wave15':barnes,'fft_historical_wave11':fft,'raytrace_historical_wave11':ray},'barnes_separate_heavy_probe_wave13':probe_out,'heldout_observed_attempt_aggregate':aggregation,'missing':missing,'separate_wave13_counterfactual_ladders':ladders,'provenance':sources}
(OUT/'components.json').write_text(json.dumps(data,indent=2)+'\n',encoding='utf-8')
fmt=lambda v:f'{v:.4f}'
lines=['# Step 1 existing-data component bound','','Derived existing evidence only: no workload, build, test, profiler, or timing was run. This is component sizing with observer overhead retained, not a measured direct-access speedup. All units below are **microseconds per complete instrumented attempt**. Missing kernel partitions remain explicit; this file does not close step 1 or a missing-proof item.','','## Six held-out regions: complete exclusive partition','','The six exclude `Chaosgame.create_image_chaos` and `Richards.run`. Source is the fresh frozen `stages/base` S18-other contexts with exact existing AOT/digest checks, not the later accepted integration. Every integer attempt partition reconciles exactly. Exclusive load excludes nested arrays; exclusive writeback excludes nested result conversion. Inclusive envelopes must not be added.','','| Region | n | Attempt | Load | Guards | Writeback | Result | Native |','|---|---:|---:|---:|---:|---:|---:|---:|']
for r in selected:
 c=r['mean_exclusive_us'];lines.append('| '+r['function']+' | '+str(r['attempts'])+' | '+fmt(r['mean_attempt_us'])+' | '+' | '.join(fmt(c[k]) for k in ['load','guards','writeback','result','native'])+' |')
other=['program_lookup','binding','arrays','array_snapshot_rollback','arena_capacity','staged_payload_copy','control_writes','recursion_frame_scan','unloader_init','result_prepare','rng_store','bookkeeping']
lines+=['','Every named other component (same exclusive partition):','','| Region | '+' | '.join(other)+' |','|---|'+'---:|'*len(other)]
for r in selected:lines.append('| '+r['function']+' | '+' | '.join(fmt(r['mean_exclusive_us'][k]) for k in other)+' |')
lines+=['','Program lookup costs, chronological, from the same attempts:','','| Region | Lookups us |','|---|---|']
for r in selected:lines.append('| '+r['function']+' | '+', '.join(fmt(v) for v in r['program_lookup_chronological_us'])+' |')
lines+=['','`transform_point` mean lookup 441.4250 us comes from a 3504.0 us first lookup and later 3.6 to 4.2 us lookups. `Task.qpkt` repeats expensive contextual lookup on six of eight attempts. Preparation is distinct from native work and cannot be removed merely by borrowing object payloads. `create_gc_cycles` has zero tracked input identities and zero input payload in the separate counting context; its 9040.7500 us result conversion chiefly materializes the returned graph. Direct input access therefore leaves its largest cost. A direct-allocation/output-identity design is needed to address that output cost.','','Separate fresh gate complete compiled/Python times (not additive or subtractable with the instrumented partition):','','| Region | Compiled us | Python us |','|---|---:|---:|']
for r in selected:lines.append('| '+r['function']+' | '+fmt(r['fresh_gate_complete_compiled_us'])+' | '+fmt(r['fresh_gate_python_us'])+' |')
lines+=['','Existing wave13 counterfactuals (separate cohorts, whole-kernel units): FFT product-to-direct saves 0.5771999859 ms, and raytrace product-to-native-original saves 1.1271000112 ms. These boundary rungs remove setup/loading/guards/writeback together; they are causal grouped counterfactual bounds, not fine component timings or a safe direct-store implementation. Raw steps are preserved in `components.json` from `ladder-v3-{scimark,raytrace}-summary.json`.','','## Kernels: separate historical/current diagnostic contexts','','| Context / region | n | Attempt | Load/pack | Guards | Writeback | Result | Native | Other |','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
for label,d,load,attempt,otherkey in [('wave15 Barnes advance_system',barnes,'load_ns','attempt_ns','other_attempt_ns'),('historical raytrace Scene.render (cold, 7 native entries)',ray,'load_ns','attempt_ns','other_attempt_ns')]:
 c=d['mean_us'];lines.append('| '+label+' | '+str(d['attempts'])+' | '+' | '.join(fmt(c[k]) for k in [attempt,load,'guards_ns','writeback_ns','result_ns','native_ns',otherkey])+' |')
for fn,d in fft['by_function'].items():
 c=d['mean_us'];lines.append('| historical FFT '+fn+' | '+str(d['attempts'])+' | '+' | '.join(fmt(c[k]) for k in ['complete_call_ns','pack_ns','guards_ns','writeback_ns'])+' | included in native | '+fmt(c['native_ns'])+' | '+fmt(c['other_ns'])+' |')
c=barnes['excluding_first_attempt']['mean_us'];lines+=['',f'Barnes excluding only the first attempt (n=499): attempt {fmt(c["attempt_ns"])}, load {fmt(c["load_ns"])}, guards {fmt(c["guards_ns"])}, writeback {fmt(c["writeback_ns"])}, result {fmt(c["result_ns"])}, native {fmt(c["native_ns"])}, residual other {fmt(c["other_attempt_ns"])} us. This explicitly described subset does not replace the all-attempt row. The all-attempt native sum / five 100-step resets is 16.11278 ms; comparing it to the separately measured 33.53 ms headline cannot establish an additive 48% share.','','FFT historical records cover 50 transforms and 50 inverses, one driver reset. Result/status conversion is inside `_run`/native. Other combines shape preparation and binding. Raytrace is a single cold attempt including preparation and seven AOT retries; its 172065.1 us other value is not a warmed steady cost. Wave13 phase scripts refer to wave11 records; no `wave13-depth/depth/work/{scimark,raytrace}/phases.json` exists. The old records above are used explicitly as historical evidence, not relabelled wave13/current product measurements.','','The separate wave13 Barnes C probe gives these diagnostic scopes per attempt; do not add them to outer Python timers or the wave15 row:','','| Probe scope | us/attempt |','|---|---:|']
for k,v in probe_out['mean_us_per_attempt'].items():lines.append('| '+k+' | '+fmt(v)+' |')
lines+=['',f'The probe has {probe_n} attempts and {ticks[-1]:,} timer switches. Range/conversion/contract work remains in graph/framework residuals. This heavy probe cannot decompose an uninstrumented boundary cost.','','## Largest contributors and dominance checks','','Across the six comparable S18 fine contexts, the three largest **individual per-call buckets** are:','']
for r in aggregation['top_individual_mean_component_us']:lines.append('- '+r['function']+' / '+r['component']+': '+fmt(r['mean_us'])+' us.')
lines+=['',f'As a deliberately count-weighted accounting of the 36 recorded attempts only, total is {fmt(total/1000)} ms. Top three component totals: '+', '.join(k+' '+fmt(v/1000)+' ms' for k,v in rank(weighted)[:3])+'. Top three region contributors: '+', '.join(k+' '+fmt(v/1000)+' ms' for k,v in rank(byregion)[:3])+'.',f'Leaving the largest region ({largest}) out leaves {fmt((total-byregion[largest])/1000)} ms; remaining top components: '+', '.join(k+' '+fmt(v/1000)+' ms' for k,v in rank(without)[:3])+'. This is an observed-attempt accounting, not a cohort-wide workload saving.','','A pooled top-three total across all nine targets is not meaningful: kernel contexts differ, raytrace is cold/retrying, and named kernel components are unresolved. Merely ranking the coarse individual magnitudes would put raytrace other (172065.1 us), raytrace native (10818.9 us), and create_gc_cycles result (9040.75 us) first; the first two are the same single cold/retrying attempt. This demonstrates why that ranking must not set the optimization priority.','','## What direct reads/stores change','','| Component | Direct read-only rule | Direct stores plus undo journal |','|---|---|---|','| load/pack | Removes arena payload copying for eligible live reads; still validates reachable shapes/types and pins owners | Same; does not remove entry guards or graph/alias checks |','| guards | Leaves necessary type, ABI, layout, shape, bounds, callable and effect guards; may combine traversals | Same, plus journal/observability/store guards |','| writeback | Removes input writeback for proven no-store regions | Replaces input arena walk/reconstruction with live publication and journal commit; cost shrinks, does not become zero |','| result | Leaves new-object boxing/materialization; returned input identity can bypass reconstruction only with explicit identity proof | Same; input journal does not optimize a newly allocated returned graph |','| program_lookup | Leaves parsing/type/program preparation and keyed signature lookup | Leaves it; separate sound cache/preparation change required |','| binding | Leaves argument binding; specialization may shrink separately | Same |','| arrays | May remove unused arena/view creation only if region needs no such ABI/storage | Same; actual arrays retain alias/stride/buffer contracts |','| array_snapshot_rollback | Leaves existing mutable array snapshot path; read-only effect proof can avoid unused snapshot | Live list/object journal does not replace buffer rollback |','| arena_capacity | Removes input arena capacity for eligible objects; output arena may remain | Same; journal capacity is a replacement cost |','| staged_payload_copy | Removes copies only for eligible direct inputs | Same; retained output/array copies remain |','| control_writes | Leaves needed status/arena/depth controls; hoist/remove only when proved unused | Same plus failure/journal controls |','| recursion_frame_scan | Leaves recursion-limit semantics unless a sound recursion summary avoids scan | Same |','| unloader_init | Removes input-only unloader initialization only when no output reconstruction remains | May shrink; new outputs still require it |','| result_prepare | Leaves necessary result metadata, alias/identity and ownership preparation | Same |','| rng_store | Leaves RNG semantics when used; skip only under effect proof of no RNG use | Same |','| bookkeeping | May shrink dispatch paths; no whole-bucket removal justified; observer overhead remains | Same; journal adds work |','| native | Changes representation and per-access loads; no measured saving follows from these timers | Adds journal/publication/reference work; unchanged body cost is not guaranteed |','','Pins, entry validation, reference handling, journal allocation/commit, and output identity preservation are replacement costs. The removable fraction inside mixed buckets is not independently measured here. R9 stays open; the table is an implementation target, not permission to discard guard obligations.','','## Missing evidence','','']
lines+=['- '+x for x in missing]
lines+=['','## Provenance','','`components.json` preserves exact raw JSON paths/pointers, all numeric tables, contextual limitations, source/artifact integrity metadata, SHA-256 of every JSON read, and count-weighted calculations. `extract_existing.py` uses only Python standard-library file reads/arithmetic and writes these two derived files in this directory. It never imports runtime sources. Raw S18 source is the frozen base, and no later depth runtime source was consulted; depth accepted source cap d86f4e3 is respected.','','Primary paths:','','- `wave14-capture/capture/s18-other/{chaos,gc_collect,hexiom,richards_super}/data.json`, `/rows/<index>/attempts/*/exclusive_ns` (exact row indices in JSON).','- `wave14-capture/capture/s18-other/summary.json`, `/rows`; `s18-report/summary.json`, `/historical_boundary/rows` for separate counts.','- `wave15-depth2/depth2/barnes-native-phase.json`, `/attempts`; wave15 runtime module digests remain in the raw record.','- `wave11-ledger/gap-ledger/work/{scimark,raytrace}/phases.json`, `/attempts`; instrumentation `gap-ledger/lift_phases.py` and `tools/_phase_worker.py`.','- `wave13-depth/depth/boundary-phases.json`, `/native_exclusive_ticks`; scope labels and warnings carried verbatim in JSON.','- Scope/reference interpretation: `wave14-capture/capture/s18-report/STARTUP-BOUNDARY.md`, `wave13-depth/REPORT.md`, `wave13-depth/depth/IN-PLACE-DESIGN.md`.','']
(OUT/'BOUND.md').write_text('\n'.join(lines),encoding='utf-8')
for name,meta in sources.items():assert hashlib.sha256((ROOT/name).read_bytes()).hexdigest()==meta['sha256'],name
print('Derived',len(selected),'held-out rows; all 36 attempt partitions reconcile; sources rehashed; no timings run.')
